// soft distant hills
for(let i=0;i<5;i++){c.fillStyle=['#7ebd79','#73ae6e','#a6ca78'][i%3];c.beginPath();c.ellipse(i*260-30,180+(i%2)*15,205,76,0,0,7);c.fill()}
const corners=[[0,0],[1000,0],[1000,600],[0,600]].map(p=>project(...p));poly(c,corners,'#7fbd68');
// tile glints on the arena floor
for(let y=55;y<590;y+=48)for(let x=22;x<990;x+=55){const [sx,sy]=project(x,y);c.fillStyle=(Math.round(x/55+y/48)%2)?'#ffffff09':'#356c3d12';c.beginPath();c.ellipse(sx,sy,24,8,0,0,7);c.fill()}
// arena wall and path, all on the ground plane
const arena=[[185,65],[815,65],[815,545],[185,545]].map(p=>project(...p));poly(c,arena,'#a4cf74');c.strokeStyle='#e7d79a';c.lineWidth=7;c.setLineDash([14,10]);c.beginPath();c.moveTo(...arena[0]);for(let i=1;i<arena.length;i++)c.lineTo(...arena[i]);c.closePath();c.stroke();c.setLineDash([]);
let p1=project(500,530),p2=project(500,470);c.strokeStyle='#b89b64';c.lineWidth=18;c.lineCap='round';c.beginPath();c.moveTo(...p1);c.lineTo(...p2);c.stroke();
for(const d of decor){const [x,y]=project(d.x,d.y);c.fillStyle='#477e48aa';c.beginPath();c.ellipse(x,y,d.r*1.4,d.r*.45,0,0,7);c.fill()}
